                    DoCast(SPELL_BURNING_SOUL);
                    events.RescheduleEvent(EVENT_1, 14000);
                    break;
                case EVENT_2:
                    DoCast(SPELL_RING_OF_SHADOWS_AT);
                    events.RescheduleEvent(EVENT_2, 24000);
                    break;
            }

        }
        DoMeleeAttackIfReady();
    }
}

