        if (!damage || me->getFaction() != 16 || instance->GetBossState(Data::BossIDs::OdynID) == DONE)
            return;

        if (instance->GetData(Data::DataMisc::OdynTestOfAges) != DONE)
        {
            if (event1)
            {
                damage = 0;
                return;
            }

            if (!ClampTrialOfValorDamage(me, attacker, damage, 25))
                return;

            event1 = true;
            DoCast(SpellRevivify);
            me->SetFlag(UNIT_FIELD_FLAGS_2, UNIT_FLAG2_REGENERATE_POWER | UNIT_FLAG2_DISABLE_TURN | UNIT_FLAG2_UNK6);

            if (instance->GetData(Data::DataMisc::OdynEventComplete2) != DONE)
            {
                instance->SetData(Data::DataMisc::OdynEventComplete2, DONE);

                if (auto owner = me->GetAnyOwner())
                    owner->GetAI()->DoAction(ACTION_1);
            }
        }
        else if (IsHeroicPlusRaid())
        {
            if (!ClampTrialOfValorDamage(me, attacker, damage, 85))
                return;

            event2 = true;
            me->CastStop();
            me->setFaction(35);
            me->RemoveAllAuras();
            me->NearTeleportTo(2404.92f, 578.45605f, 772.8941f, 5.05401f);
            instance->SendEncounterUnit(ENCOUNTER_FRAME_DISENGAGE, me);
        }
    }

    void SpellFinishCast(SpellInfo const* spell) override
    {
        switch (spell->Id)
        {
        case SpellRevivify:
            event1 = false;
            me->RemoveFlag(UNIT_FIELD_FLAGS_2, UNIT_FLAG2_REGENERATE_POWER | UNIT_FLAG2_DISABLE_TURN | UNIT_FLAG2_UNK6);

            if ((instance->GetData(Data::DataMisc::OdynEventComplete2) == DONE) && (instance->GetData(Data::DataMisc::OdynEventComplete1) != DONE))
                instance->SetData(Data::DataMisc::OdynEventComplete2, FAIL);
        default:
            break;
        }
    }

    void EnterEvadeMode() override
    {
        if ((instance->GetData(Data::DataMisc::OdynIntroEvent) == DONE) && (instance->GetData(Data::DataMisc::OdynEventComplete2) != DONE))
        {
            if (auto owner = me->GetAnyOwner())
                owner->GetAI()->DoAction(ACTION_3);
        }

        ScriptedAI::EnterEvadeMode();
    }

    void KilledUnit(Unit* victim) override
    {
        if (!victim->IsPlayer())
            return;

        Talk(SAY_DIE_TANK);
    }

