struct npc_invasion_stormheim_dragonsAI : ScriptedAI
    {
        npc_invasion_stormheim_dragonsAI(Creature* creature) : ScriptedAI(creature)
        {
            timerforcheck  = 1000;
            check = false;
            me->SetReactState(REACT_PASSIVE);
        }

        uint32 timerforcheck;
        bool check;

        void IsSummonedBy(Unit* summoner) override
        {
            SetFlyMode(true);
            summoner->CastSpell(me, 52391, true); //Ride Veh
        }

        void OnCharmed(bool /*apply*/) override
        {

        }

        uint64 boardingGeneration = 0;
        ObjectGuid boardedPlayerGuid;
        bool scriptedControl = false;

        void PassengerBoarded(Unit* who, int8 /*seatId*/, bool apply) override
        {
            if (!who || !who->IsPlayer())
                return;

            if (!apply)
            {
                if (who->GetGUID() != boardedPlayerGuid)
                    return;
                ++boardingGeneration;
                if (scriptedControl)
                    who->ToPlayer()->SetClientControl(who, true);
                scriptedControl = false;
                boardedPlayerGuid.Clear();
                return;
            }

            if (who->GetVehicleBase() != me || boardedPlayerGuid == who->GetGUID())
                return;

            boardedPlayerGuid = who->GetGUID();
            uint64 const generation = ++boardingGeneration;
            me->AddDelayedEvent(2000, [this, playerGuid = boardedPlayerGuid, generation]() -> void
            {
                if (generation != boardingGeneration || playerGuid != boardedPlayerGuid)
                    return;
                Player* player = ObjectAccessor::GetPlayer(*me, playerGuid);
                if (!player || !player->IsAlive() || player->GetVehicleBase() != me)
                    return;

                player->SetClientControl(me, false);
                scriptedControl = true;
                me->AddDelayedEvent(3000, [this, playerGuid, generation]() -> void
                {
                    if (generation != boardingGeneration || playerGuid != boardedPlayerGuid)
                        return;
                    Player* player = ObjectAccessor::GetPlayer(*me, playerGuid);
                    if (!player || !player->IsAlive() || player->GetVehicleBase() != me)
                        return;

                    me->GetMotionMaster()->MovePath((urand(1, 2) == 1 ? 10993814 : 10993815), true, irand(-20, 20), irand(-20, 20));
                });
            });
        }

        void MovementInform(uint32 moveType, uint32 pointId) override
        {
            if (moveType != WAYPOINT_MOTION_TYPE)
                return;

            if (!check)
                return;

            if (me->GetVehicleKit() && pointId == 12)
            {
                if (Unit* passenger = me->GetVehicleKit()->GetPassenger(0))
                {
                    passenger->ToPlayer()->UpdateAchievementCriteria(CRITERIA_TYPE_SCRIPT_EVENT_2, 56604);
                    passenger->AddAura(55001, passenger);
                    me->GetVehicleKit()->RemoveAllPassengers();
                    me->DespawnOrUnsummon(500);
                }
            }
        }

        void UpdateAI(uint32 diff) override
        {
            if (!check)
            {
                if (timerforcheck <= diff)
                {
                    if (me->GetAnyOwner())
                        if (InstanceScript* instance = me->GetInstanceScript())
                            if (instance->getScenarionStep() == 2)
                            {
                                check = true;
                                me->GetMotionMaster()->MovePath(10993816, false);
                            }

                    timerforcheck = 1000;
                }
                else
                    timerforcheck -= diff;
            }
        }
    }

